```yaml
name: Remove SLO label

on:
  workflow_run:
    workflows: ["SLO"]
    types: [completed]

permissions:
  contents: read
  issues: write

jobs:
  remove-slo-label:
    if: ${{ always() && github.event.workflow_run.pull_requests && github.event.workflow_run.pull_requests.length > 0 }}
    runs-on: ubuntu-latest
    steps:
      - name: Remove SLO label
        uses: actions/github-script@v7
        with:
          script: |
            const prNumber = github.event.workflow_run.pull_requests[0].number;
            try {
              await github.rest.issues.removeLabel({
                owner: context.repo.owner,
                repo: context.repo.repo,
                issue_number: prNumber,
                name: 'SLO'
              });
              console.log(`Removed SLO label from PR #${prNumber}`);
            } catch (error) {
              if (error.status !== 404) {
                throw error;
              } else {
                console.log(`SLO label not found on PR #${prNumber}`);
              }
            }
